function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var TX='<svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><path d="M2 2l8 8M10 2l-8 8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>';
function kitToast(host,tone,inline){var t=document.createElement('div');t.className='toast '+tone;t.setAttribute('role','status');if(inline){t.style.position='static';t.style.width='auto';}t.innerHTML='<span class="toast-title">'+(tone==='red'?'Check failed':'Stop-loss')+'</span><button class="toast-close" type="button" aria-label="Dismiss">'+TX+'</button><p class="toast-msg">'+(tone==='red'?'The token gate failed on this page; fix it before it ships.':'No new build before the Friday triage. Income first.')+'</p><span class="toast-meta">2026-11-11 · 16:00 ET · set by the recoil</span>';t.querySelector('button').addEventListener('click',function(){t.hidden=true});host.appendChild(t);return t}
kitToast(kSlot(),'gold',true);
STATES.forEach(function(a,i){kitToast(kSlot(i),a[0],true)});
